use crate::identity::{Entry, Identity, Kind, LIFE_CATEGORIES};
use std::collections::BTreeMap;

pub const MARKER: &str =
    "<!-- generated by `owo index`; edit the sources and rerun `owo index` -->";

fn heading(category: &str) -> String {
    let mut c = category.chars();
    match c.next() {
        Some(f) => f.to_uppercase().chain(c).collect(),
        None => String::new(),
    }
}

fn line(e: &Entry) -> String {
    let title = e.label();
    let mut out = format!("- [[{title}]]");
    let marks: Vec<String> = [
        e.field_str("state").filter(|s| s != "open"),
        e.field_str("status").filter(|s| s != "canon"),
    ]
    .into_iter()
    .flatten()
    .collect();
    if !marks.is_empty() {
        out.push_str(&format!(" ({})", marks.join(", ")));
    }
    if let Some(s) = e.field_str("summary").filter(|s| !s.trim().is_empty()) {
        out.push_str(&format!(": {}", s.trim()));
    }
    if !e.aliases.is_empty() {
        out.push_str(&format!(" (aliases: {})", e.aliases.join(", ")));
    }
    out
}

fn doc(title: &str, lines: &[String]) -> String {
    let mut out = format!("{MARKER}\n# {title}\n\n");
    if lines.is_empty() {
        out.push_str("Empty.\n");
    } else {
        for l in lines {
            out.push_str(l);
            out.push('\n');
        }
    }
    out
}

fn in_folder<'a>(identity: &'a Identity, prefix: &str) -> Vec<&'a Entry> {
    identity
        .entries
        .iter()
        .filter(|e| !e.is_generated() && e.rel.starts_with(prefix))
        .collect()
}

pub fn generate(identity: &Identity) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    let mut top = vec![];
    for (category, kind) in LIFE_CATEGORIES {
        let prefix = format!("life/{category}/");
        let entries = in_folder(identity, &prefix);
        let lines: Vec<String> = if *kind == Kind::Location {
            let mut lines = vec![];
            for overview in entries.iter().filter(|e| e.kind == Kind::Location) {
                lines.push(line(overview));
                let folder = overview.rel.trim_end_matches("overview.md");
                for detail in entries
                    .iter()
                    .filter(|e| e.kind == Kind::LocationDetail && e.rel.starts_with(folder))
                {
                    lines.push(format!("  {}", line(detail)));
                }
            }
            lines
        } else {
            entries
                .iter()
                .filter(|e| e.kind == *kind)
                .map(|e| line(e))
                .collect()
        };
        let count = entries.iter().filter(|e| e.kind == *kind).count();
        top.push(format!(
            "- [{}]({category}/_index.md): {count}",
            heading(category)
        ));
        out.insert(
            format!("{prefix}_index.md"),
            doc(&heading(category), &lines),
        );
    }
    top.push("- [Timeline](timeline.md)".into());
    out.insert("life/_index.md".into(), doc("Life", &top));
    out.insert("life/timeline.md".into(), timeline(identity));
    out.insert("work/_index.md".into(), work(identity));
    out
}

fn timeline(identity: &Identity) -> String {
    let eras: Vec<&Entry> = identity
        .entries
        .iter()
        .filter(|e| e.kind == Kind::Era)
        .collect();
    let mut events: Vec<&Entry> = identity
        .entries
        .iter()
        .filter(|e| e.kind == Kind::Event)
        .collect();
    events.sort_by_key(|e| (e.field_str("date").unwrap_or_default(), e.rel.clone()));
    let event_line = |e: &Entry| {
        let date = e.field_str("date").unwrap_or_else(|| "undated".into());
        let mut l = line(e);
        l.replace_range(0..2, &format!("- {date}: "));
        l
    };
    let era_of: Vec<Option<String>> = events
        .iter()
        .map(|ev| {
            let value = ev.field_str("era")?;
            let target = crate::markdown::links(&value)
                .first()
                .map(|l| l.target.clone())
                .unwrap_or(value);
            match identity.resolve_link(&target)[..] {
                [i] if identity.entries[i].kind == Kind::Era => {
                    Some(identity.entries[i].rel.clone())
                }
                _ => None,
            }
        })
        .collect();
    let mut lines = vec![];
    let mut placed = vec![false; events.len()];
    let mut sorted_eras = eras.clone();
    sorted_eras.sort_by_key(|e| (e.field_str("start").unwrap_or_default(), e.rel.clone()));
    for era in sorted_eras {
        let title = era.label();
        lines.push(format!("\n## {title}\n"));
        for (i, ev) in events.iter().enumerate() {
            if era_of[i].as_deref() == Some(era.rel.as_str()) {
                placed[i] = true;
                lines.push(event_line(ev));
            }
        }
    }
    let rest: Vec<String> = events
        .iter()
        .enumerate()
        .filter(|(i, _)| !placed[*i])
        .map(|(_, e)| event_line(e))
        .collect();
    if !rest.is_empty() && !lines.is_empty() {
        lines.push("\n## Other events\n".into());
    }
    lines.extend(rest);
    doc("Timeline", &lines)
}

fn work(identity: &Identity) -> String {
    let mut lines = vec!["- [Profile](README.md)".to_string()];
    for project in identity.entries.iter().filter(|e| e.kind == Kind::Project) {
        let notes = identity.notes(&project.stem_key()).len();
        lines.push(format!("{} ({notes} notes)", line(project)));
    }
    doc("Work", &lines)
}

pub fn write(identity: &Identity) -> anyhow::Result<Vec<String>> {
    write_as(identity, &identity.dir)
}

pub fn write_as(identity: &Identity, shown: &std::path::Path) -> anyhow::Result<Vec<String>> {
    let stale = differing(identity);
    stale
        .iter()
        .fold(crate::write::Writes::new(), |w, (rel, content)| {
            w.file(identity.dir.join(rel), shown.join(rel), content.as_str())
        })
        .commit()?;
    Ok(stale.into_iter().map(|(rel, _)| rel).collect())
}

pub fn stale(identity: &Identity) -> Vec<String> {
    differing(identity)
        .into_iter()
        .map(|(rel, _)| rel)
        .collect()
}

fn differing(identity: &Identity) -> Vec<(String, String)> {
    generate(identity)
        .into_iter()
        .filter(|(rel, content)| {
            crate::write::read_to_string(&identity.dir.join(rel))
                .ok()
                .as_deref()
                != Some(content.as_str())
        })
        .collect()
}
